# region: digest
def digest(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: render
def render(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs):
    return {'n': len(xs), 'total': max(xs)}

# region: sift
def sift(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return sift(intake(render(gather(digest(raw)))))

