        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 2, 'total': 6, 'grade': 'low'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 1, 'total': 4, 'grade': 'low'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 1, 'total': 6, 'grade': 'low'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 2, 'total': 6, 'grade': 'low'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 0, 'total': 0, 'grade': 'low'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 2, 'total': 6, 'grade': 'low'})
    def test_case_07(self):
        self.assertEqual(run(['2', 'hello', '40']), {'n': 2, 'total': 14, 'grade': 'low'})

